function initialState(): PersistedAppState {
  const session = createSession();
  return {
    schemaVersion: 1,
    sessions: [session],
    activeSessionId: session.id,
    artifacts: [],
    providerSettings: DEFAULT_PROVIDER_SETTINGS,
    learnerFeedback: { helpful: 0, missed: 0 },
  };
}

function normalizeState(candidate: PersistedAppState | null): PersistedAppState {
  if (!candidate || candidate.sessions.length === 0) return initialState();
  const activeExists = candidate.sessions.some((session) => session.id === candidate.activeSessionId);
  return {
    ...candidate,
    activeSessionId: activeExists ? candidate.activeSessionId : candidate.sessions[0].id,
    artifacts: Array.isArray(candidate.artifacts) ? candidate.artifacts : [],
    learnerFeedback: candidate.learnerFeedback ?? { helpful: 0, missed: 0 },
    providerSettings: candidate.providerSettings ?? DEFAULT_PROVIDER_SETTINGS,
  };
}

function titleFromFirstMessage(content: string): string {
  const title = content.replace(/\s+/g, " ").trim();
  return title.length > 48 ? `${title.slice(0, 47)}…` : title || "New lesson";
}

function artifactTitle(message: ChatMessage, kind: ArtifactKind): string {
  const firstLine = message.content
    .split("\n")
    .map((line) => line.replace(/^#+\s*/, "").trim())
    .find(Boolean);
  if (firstLine) return firstLine.length > 64 ? `${firstLine.slice(0, 63)}…` : firstLine;
  return kind === "study-plan" ? "Study plan" : kind === "quiz" ? "Practice quiz" : "Saved note";
}

const KeatingContext = createContext<KeatingContextValue | null>(null);

export function KeatingProvider({ children }: PropsWithChildren) {
  const [state, setState] = useState<PersistedAppState>(initialState);
  const [hydrated, setHydrated] = useState(false);
  const [storageError, setStorageError] = useState<string | null>(null);
  const [generationError, setGenerationError] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [keyStatus, setKeyStatus] = useState<KeyStatus>(emptyKeyStatus);
  const stateRef = useRef(state);

import { KEATING_MOBILE_SYSTEM_PROMPT } from "./system-prompt";
import type { ChatMessage, ProviderSettings } from "./types";

export type FetchLike = (input: string, init?: RequestInit) => Promise<Response>;

export interface ProviderRequest {
  url: string;
  init: RequestInit;
}

const MAX_HISTORY_MESSAGES = 40;

function withoutTrailingSlash(value: string): string {
  return value.trim().replace(/\/+$/, "");
}

function openAiChatUrl(baseUrl: string): string {
  const base = withoutTrailingSlash(baseUrl);
  if (base.endsWith("/chat/completions")) return base;
  if (base.endsWith("/v1")) return `${base}/chat/completions`;
  return `${base}/v1/chat/completions`;
}

function recentMessages(messages: ChatMessage[]) {
  return messages
    .filter((message) => message.content.trim().length > 0)
    .slice(-MAX_HISTORY_MESSAGES);
}

export function buildProviderRequest(
  settings: ProviderSettings,
  apiKey: string | null,
  messages: ChatMessage[],
  signal?: AbortSignal,
): ProviderRequest {
  const history = recentMessages(messages);
  const commonHeaders: Record<string, string> = { "Content-Type": "application/json" };

  if (settings.provider === "anthropic") {
    if (apiKey) commonHeaders["x-api-key"] = apiKey;
    commonHeaders["anthropic-version"] = "2023-06-01";
    return {
      url: `${withoutTrailingSlash(settings.baseUrl)}/messages`,
      init: {
        method: "POST",
        headers: commonHeaders,
        signal,
        body: JSON.stringify({
          model: settings.model,
          system: KEATING_MOBILE_SYSTEM_PROMPT,
          max_tokens: 4096,
          temperature: settings.temperature,
          messages: history.map((message) => ({ role: message.role, content: message.content })),
        }),
      },
    };
  }

  if (settings.provider === "google") {
    const encodedModel = encodeURIComponent(settings.model);
    const keyQuery = apiKey ? `?key=${encodeURIComponent(apiKey)}` : "";
    return {
      url: `${withoutTrailingSlash(settings.baseUrl)}/models/${encodedModel}:generateContent${keyQuery}`,
      init: {
        method: "POST",
        headers: commonHeaders,
        signal,
        body: JSON.stringify({
          systemInstruction: { parts: [{ text: KEATING_MOBILE_SYSTEM_PROMPT }] },
          contents: history.map((message) => ({
            role: message.role === "assistant" ? "model" : "user",
            parts: [{ text: message.content }],
          })),
          generationConfig: { temperature: settings.temperature, maxOutputTokens: 4096 },
        }),
      },
    };
  }

  if (apiKey) commonHeaders.Authorization = `Bearer ${apiKey}`;
  if (settings.provider === "openrouter") {
    commonHeaders["HTTP-Referer"] = "https://keating.help";
    commonHeaders["X-Title"] = "Keating Mobile";
  }

  return {
    url: openAiChatUrl(settings.baseUrl),
    init: {
      method: "POST",
      headers: commonHeaders,
      signal,
      body: JSON.stringify({
        model: settings.model,
        temperature: settings.temperature,
        messages: [
          { role: "system", content: KEATING_MOBILE_SYSTEM_PROMPT },
          ...history.map((message) => ({ role: message.role, content: message.content })),
        ],
      }),
    },
  };
}

function providerErrorMessage(payload: unknown, fallback: string): string {
  if (typeof payload !== "object" || payload === null) return fallback;
  const record = payload as Record<string, unknown>;
  const error = record.error;
  if (typeof error === "string" && error.trim()) return error;
  if (typeof error === "object" && error !== null) {
    const message = (error as Record<string, unknown>).message;
    if (typeof message === "string" && message.trim()) return message;
  }
  const message = record.message;
  return typeof message === "string" && message.trim() ? message : fallback;
}

function extractProviderText(settings: ProviderSettings, payload: unknown): string {
  const record = payload as Record<string, any>;
  if (settings.provider === "anthropic") {
    const text = Array.isArray(record.content)
      ? record.content.filter((block: any) => block?.type === "text").map((block: any) => block.text).join("\n")
      : "";
    if (text.trim()) return text.trim();
  } else if (settings.provider === "google") {
    const text = record.candidates?.[0]?.content?.parts
      ?.map((part: any) => typeof part?.text === "string" ? part.text : "")
      .join("\n");
    if (typeof text === "string" && text.trim()) return text.trim();
  } else {
    const content = record.choices?.[0]?.message?.content;
    if (typeof content === "string" && content.trim()) return content.trim();
    if (Array.isArray(content)) {
      const text = content.map((part: any) => part?.text ?? "").join("\n");
      if (text.trim()) return text.trim();
    }
  }
  throw new Error("The provider returned a response without readable text.");
}

export async function requestCompletion(
  settings: ProviderSettings,
  apiKey: string | null,
  messages: ChatMessage[],
  signal?: AbortSignal,
  fetchImpl: FetchLike = fetch,
): Promise<string> {
  const request = buildProviderRequest(settings, apiKey, messages, signal);
  const response = await fetchImpl(request.url, request.init);
  const responseText = await response.text();
  let payload: unknown = {};
  try {
    payload = responseText ? JSON.parse(responseText) : {};
  } catch {
    if (!response.ok) throw new Error(`Provider request failed with HTTP ${response.status}.`);
    throw new Error("The provider returned an invalid JSON response.");
  }

  if (!response.ok) {
    throw new Error(providerErrorMessage(payload, `Provider request failed with HTTP ${response.status}.`));
  }
  return extractProviderText(settings, payload);
}
export const KEATING_MOBILE_SYSTEM_PROMPT = `You are Keating, a hyperteacher dedicated to preserving the learner's own voice through cognitive empowerment.

Teach for mastery rather than surface agreement. Keep the learner active through a loop of diagnosis, intuition, formal core, misconception repair, worked example, retrieval, and reflection. Ask short questions and invite predictions or reconstructions. Do not replace the learner's thinking with a polished answer when a scaffold would teach more.

Adapt to the domain. For mathematics, reach the formalism. For science, connect claims to measurement and prediction. For code, include runnable examples and traces. For law, medicine, history, psychology, politics, or the arts, make evidence, uncertainty, competing interpretations, and concrete sources explicit. Never present an unverified factual claim as settled.

Use clear Markdown that reads well on a phone. Prefer short sections, compact lists, and one useful next question. When asked for a study plan, quiz, or explanation, produce a self-contained artifact that the learner can save locally.`;
