import {
	createAssistantMessageEventStream,
	type Api,
	type AssistantMessage,
	type Context,
	type Model,
	type SimpleStreamOptions,
} from "@earendil-works/pi-ai";
import { streamSimple } from "@earendil-works/pi-ai/compat";
import { normalizeToolCallStream } from "../keating/tool-call-normalizer";
import { streamWithApiRetry } from "../keating/api-retry";
import { chatProxyBaseUrl, proxyTargetHeader, shouldProxyModel } from "../lib/provider-proxy";
import { DIO_DEFAULT_MODEL } from "../dio-provider";
import {
	applyGoogleSearchGrounding,
	applyProviderWebSearch,
	resolveProviderWebSearchRoute,
} from "../keating/provider-web-search";
import { signalHostedSearchActivation } from "../keating/search";

// Compatibility exports for existing integrations and tests. New routing should
// prefer applyProviderWebSearch so capability negotiation stays centralized.
export { applyGoogleSearchGrounding, applyProviderWebSearch };
import { getProviderApiKey } from "../lib/provider-models";
import { localModel, getModelName, getModelId } from "../stores/local-model";

export const DEFAULT_MODEL = DIO_DEFAULT_MODEL;

export function withProviderWebSearch(
	options: SimpleStreamOptions | undefined,
	model: Model<Api>,
	hasApiKey: boolean,
): SimpleStreamOptions | undefined {
	if (model.provider !== "google" && model.provider !== "openai" && model.provider !== "anthropic") {
		return options;
	}
	let signalled = false;

	return {
		...options,
		onPayload: async (payload, payloadModel) => {
			const userPayload = await options?.onPayload?.(payload, payloadModel);
			const nextPayload = userPayload ?? payload;
			const groundedPayload = applyProviderWebSearch(nextPayload, payloadModel, hasApiKey);
			if (groundedPayload !== undefined && !signalled) {
				signalled = true;
				signalHostedSearchActivation(resolveProviderWebSearchRoute(payloadModel, hasApiKey));
			}
			return groundedPayload ?? userPayload;
		},
	};
}

function createBrowserStreamFn() {
	return async (_model: Model<Api>, context: Context, options?: SimpleStreamOptions) => {
		const stream = createAssistantMessageEventStream();
		const abortSignal = options?.signal;

		const defaultFields = {
			api: "browser" as const,
			provider: "browser" as const,
			model: getModelId(),
			usage: {
				input: 0,
				output: 0,
				cacheRead: 0,
				cacheWrite: 0,
				totalTokens: 0,
				cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
			},
		};

		(async () => {
			try {
				if (abortSignal?.aborted) {
					stream.end({
						...defaultFields,
						role: "assistant",
						content: [],
						stopReason: "aborted",
						errorMessage: "Request aborted",
						timestamp: Date.now(),
					} as AssistantMessage);
					return;
				}

				const userMessages = context.messages
					.filter((m): m is Extract<typeof m, { role: "user" }> => m.role === "user")
					.map((m) => {
						const content = m.content;
						if (typeof content === "string") return content;
						return content
							.filter((c): c is Extract<typeof c, { type: "text" }> => c.type === "text")
							.map((c) => c.text)
							.join("\n");
					});

				const systemPrompt = context.systemPrompt || "";
				const conversationHistory = userMessages.join("\n\n");
				const fullPrompt = systemPrompt
					? `${systemPrompt}\n\n${conversationHistory}`
					: conversationHistory;

				const partialMessage: AssistantMessage = {
					...defaultFields,
					role: "assistant",
					content: [{ type: "text", text: "" }],
					stopReason: "stop",
					timestamp: Date.now(),
				};

				stream.push({ type: "start", partial: partialMessage });
				stream.push({ type: "text_start", contentIndex: 0, partial: partialMessage });

				const response = await localModel.generate(
					fullPrompt,
					{ max_length: options?.maxTokens ?? 1024, temperature: options?.temperature ?? 0.7 },
					(token: string) => {
						const textBlock = partialMessage.content[0];
						if (textBlock.type === "text") textBlock.text += token;
						stream.push({ type: "text_delta", contentIndex: 0, delta: token, partial: partialMessage });
					},
				);

				if (abortSignal?.aborted) {
					stream.end({
						...defaultFields,
						role: "assistant",
						content: [{ type: "text", text: response }],
						stopReason: "aborted",
						errorMessage: "Request aborted",
						timestamp: Date.now(),
					} as AssistantMessage);
					return;
				}

				stream.push({
					type: "text_end",
					contentIndex: 0,
					content: response,
					partial: partialMessage,
				});
				stream.end({
					...defaultFields,
					role: "assistant",
					content: [{ type: "text", text: response }],
					stopReason: "stop",
					timestamp: Date.now(),
				} as AssistantMessage);
			} catch (error) {
				stream.end({
					...defaultFields,
					role: "assistant",
					content: [],
					stopReason: "error",
					errorMessage: error instanceof Error ? error.message : String(error),
					timestamp: Date.now(),
				} as AssistantMessage);
			}
		})();

		return stream;
	};
}

export async function hybridStreamFn(model: Model<Api>, context: Context, options?: SimpleStreamOptions) {
	if (model.provider === "browser") {
		return normalizeToolCallStream(await createBrowserStreamFn()(model, context, options), context);
	}

	const apiKey = options?.apiKey ?? await getProviderApiKey(model.provider);
	const streamOptions: SimpleStreamOptions | undefined = apiKey ? { ...options, apiKey } : options;

	if (shouldProxyModel(model)) {
		const proxiedModel = {
			...model,
			baseUrl: chatProxyBaseUrl(),
		};
		const proxiedOptions: SimpleStreamOptions = {
			...streamOptions,
			headers: {
				...streamOptions?.headers,
				"x-target-url": proxyTargetHeader(model.baseUrl),
			},
		};
		if (import.meta.env.DEV) {
			const hasApiKey = !!proxiedOptions.apiKey;
			console.log(`[keating:stream] proxy ${model.provider} -> ${model.baseUrl} (apiKey=${hasApiKey})`);
		}
		const mergedOptions = withProviderWebSearch(proxiedOptions, proxiedModel, !!apiKey);
		return normalizeToolCallStream(
			streamWithApiRetry(proxiedModel, context, mergedOptions, (nextOptions) => streamSimple(proxiedModel, context, nextOptions)),
			context,
		);
	}

	const mergedOptions = withProviderWebSearch(streamOptions, model, !!apiKey);
	return normalizeToolCallStream(
		streamWithApiRetry(model, context, mergedOptions, (nextOptions) => streamSimple(model, context, nextOptions)),
		context,
	);
}

  const stateRef = useRef(state);
  const abortControllerRef = useRef<AbortController | null>(null);

  stateRef.current = state;

  useEffect(() => {
    let cancelled = false;
    Promise.all([
      loadPersistedState(),
      Promise.all(PROVIDERS.map(async (provider) => [provider.id, Boolean(await getProviderKey(provider.id))] as const)),
    ])
      .then(([persisted, keys]) => {
        if (cancelled) return;
        const next = normalizeState(persisted);
        stateRef.current = next;
        setState(next);
        setKeyStatus(Object.fromEntries(keys) as KeyStatus);
      })
      .catch((error) => {
        if (!cancelled) setStorageError(error instanceof Error ? error.message : "Could not load local learning data.");
      })
      .finally(() => {
        if (!cancelled) setHydrated(true);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (!hydrated) return;
    const timeout = setTimeout(() => {
      savePersistedState(state).catch((error) => {
        setStorageError(error instanceof Error ? error.message : "Could not save local learning data.");
      });
    }, 120);
    return () => clearTimeout(timeout);
  }, [hydrated, state]);

  const activeSession = useMemo(
    () => state.sessions.find((session) => session.id === state.activeSessionId) ?? state.sessions[0],
    [state.activeSessionId, state.sessions],
  );

  const updateSession = useCallback((sessionId: string, update: (session: ChatSession) => ChatSession) => {
    setState((current) => ({
      ...current,
      sessions: current.sessions.map((session) => session.id === sessionId ? update(session) : session),
    }));
  }, []);

  const runCompletion = useCallback(async (sessionId: string, messages: ChatMessage[]) => {
    const snapshot = stateRef.current;
    const settings = snapshot.providerSettings;
    const definition = providerDefinition(settings.provider);
    setGenerationError(null);

    const apiKey = await getProviderKey(settings.provider);
    if (definition.requiresKey && !apiKey) {
      setGenerationError(`Add your ${definition.label} API key in Settings before sending a message.`);
      return;
    }

    const controller = new AbortController();
    abortControllerRef.current = controller;
    setIsGenerating(true);
    try {
      const content = await requestCompletion(settings, apiKey, messages, controller.signal);
      const assistantMessage: ChatMessage = {
        id: createId("message"),
        role: "assistant",
        content,
        createdAt: Date.now(),
      };
      updateSession(sessionId, (session) => ({
        ...session,
        messages: [...session.messages, assistantMessage],
        updatedAt: assistantMessage.createdAt,
      }));
      void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success).catch(() => undefined);
    } catch (error) {
      if (error instanceof Error && error.name === "AbortError") return;
      setGenerationError(error instanceof Error ? error.message : "The model request failed.");
      void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error).catch(() => undefined);
    } finally {
      if (abortControllerRef.current === controller) {
        abortControllerRef.current = null;
        setIsGenerating(false);
      }
    }
  }, [updateSession]);

  const sendMessage = useCallback(async (content: string) => {
    const trimmed = content.trim();
    if (!trimmed || isGenerating) return;
    const current = stateRef.current;
    const session = current.sessions.find((entry) => entry.id === current.activeSessionId) ?? current.sessions[0];
    const message: ChatMessage = {
      id: createId("message"),
      role: "user",
      content: trimmed,
      createdAt: Date.now(),
    };
    const messages = [...session.messages, message];
    updateSession(session.id, (entry) => ({
      ...entry,
      title: entry.messages.length === 0 ? titleFromFirstMessage(trimmed) : entry.title,
      messages,
      updatedAt: message.createdAt,
    }));
    await runCompletion(session.id, messages);
  }, [isGenerating, runCompletion, updateSession]);

  const retryLastResponse = useCallback(async () => {
    if (isGenerating) return;
    const current = stateRef.current;
    const session = current.sessions.find((entry) => entry.id === current.activeSessionId) ?? current.sessions[0];
    let userIndex = -1;
    for (let index = session.messages.length - 1; index >= 0; index -= 1) {
      if (session.messages[index].role === "user") {
        userIndex = index;
        break;
      }
    }
    if (userIndex < 0) return;
    const messages = session.messages.slice(0, userIndex + 1);
    updateSession(session.id, (entry) => ({ ...entry, messages, updatedAt: Date.now() }));
    await runCompletion(session.id, messages);
  }, [isGenerating, runCompletion, updateSession]);

  const stopGeneration = useCallback(() => {
    abortControllerRef.current?.abort();
    abortControllerRef.current = null;
    setIsGenerating(false);
  }, []);

  const newSession = useCallback(() => {
    stopGeneration();
    const session = createSession();
    setState((current) => ({
      ...current,
      sessions: [session, ...current.sessions],
      activeSessionId: session.id,
    }));
    void Haptics.selectionAsync().catch(() => undefined);
    return session.id;
  }, [stopGeneration]);

  const selectSession = useCallback((sessionId: string) => {
    if (!stateRef.current.sessions.some((session) => session.id === sessionId)) return;
    stopGeneration();
    setState((current) => ({ ...current, activeSessionId: sessionId }));
  }, [stopGeneration]);

  const deleteSession = useCallback((sessionId: string) => {
    stopGeneration();
    setState((current) => {
      const remaining = current.sessions.filter((session) => session.id !== sessionId);
      if (remaining.length === 0) remaining.push(createSession());
      return {
        ...current,
        sessions: remaining,
        activeSessionId: current.activeSessionId === sessionId ? remaining[0].id : current.activeSessionId,
        artifacts: current.artifacts.filter((artifact) => artifact.sessionId !== sessionId),
      };
    });
  }, [stopGeneration]);

  const setMessageFeedback = useCallback((messageId: string, feedback: MessageFeedback) => {
    setState((current) => {
      let previous: MessageFeedback | undefined;
      const sessions = current.sessions.map((session) => ({
        ...session,
        messages: session.messages.map((message) => {
          if (message.id !== messageId) return message;
          previous = message.feedback;
          return { ...message, feedback };
        }),
      }));
      if (!previous && sessions.every((session) => session.messages.every((message) => message.id !== messageId))) {
        return current;
      }
      const learnerFeedback = { ...current.learnerFeedback };
      if (previous) learnerFeedback[previous] = Math.max(0, learnerFeedback[previous] - 1);
      learnerFeedback[feedback] += 1;
      return { ...current, sessions, learnerFeedback };
    });
    void Haptics.selectionAsync().catch(() => undefined);
  }, []);

  const saveArtifact = useCallback((messageId: string, kind: ArtifactKind = "note") => {
    setState((current) => {
      if (current.artifacts.some((artifact) => artifact.messageId === messageId)) return current;
      const session = current.sessions.find((entry) => entry.messages.some((message) => message.id === messageId));
      const message = session?.messages.find((entry) => entry.id === messageId);
      if (!session || !message || message.role !== "assistant") return current;
      return {
        ...current,
        artifacts: [{
          id: createId("artifact"),
          sessionId: session.id,
          messageId,
          kind,
          source: "assistant",
          title: artifactTitle(message, kind),
          content: message.content,
          createdAt: Date.now(),
        }, ...current.artifacts],
      };
    });
    void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success).catch(() => undefined);
  }, []);

  const createLearningArtifact = useCallback((topicName: string, kind: GeneratedArtifactKind) => {
    const generated = generateLearningArtifact(topicName, kind);
    const id = createId("artifact");
    setState((current) => ({
      ...current,
      artifacts: [{
        id,
        kind: generated.kind,
        source: "keating-core",
        topic: generated.topic,
        title: generated.title,
        content: generated.content,
        createdAt: Date.now(),
      }, ...current.artifacts],
    }));
    void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success).catch(() => undefined);
    return id;
  }, []);

  const deleteArtifact = useCallback((artifactId: string) => {
    setState((current) => ({
      ...current,
      artifacts: current.artifacts.filter((artifact) => artifact.id !== artifactId),
    }));
  }, []);

  const setProvider = useCallback((provider: ProviderId) => {
    setState((current) => ({ ...current, providerSettings: settingsForProvider(provider) }));
  }, []);

  const updateProviderSettings = useCallback((patch: Partial<ProviderSettings>) => {
    setState((current) => ({
      ...current,
      providerSettings: { ...current.providerSettings, ...patch },
    }));
  }, []);

  const saveApiKey = useCallback(async (provider: ProviderId, apiKey: string) => {
    const trimmed = apiKey.trim();
    if (!trimmed) throw new Error("Enter an API key before saving.");
    await setProviderKey(provider, trimmed);
    setKeyStatus((current) => ({ ...current, [provider]: true }));
  }, []);

  const removeApiKey = useCallback(async (provider: ProviderId) => {
    await deleteProviderKey(provider);
    setKeyStatus((current) => ({ ...current, [provider]: false }));
  }, []);

  const clearLearningData = useCallback(async () => {
    stopGeneration();
    await clearPersistedState();
    const next = initialState();
    stateRef.current = next;
    setState(next);
  }, [stopGeneration]);

  const definition = providerDefinition(state.providerSettings.provider);
  const isProviderConfigured = !definition.requiresKey || keyStatus[state.providerSettings.provider];

  const value = useMemo<KeatingContextValue>(() => ({
    state,
    activeSession,
    hydrated,
    storageError,
    generationError,
    isGenerating,
    keyStatus,
    isProviderConfigured,
    sendMessage,
    retryLastResponse,
    stopGeneration,
    clearGenerationError: () => setGenerationError(null),
    newSession,
    selectSession,
    deleteSession,
    setMessageFeedback,
    saveArtifact,
    createLearningArtifact,
    deleteArtifact,
    setProvider,
    updateProviderSettings,
    saveApiKey,
    removeApiKey,
    clearLearningData,
  }), [
    state, activeSession, hydrated, storageError, generationError, isGenerating, keyStatus,
    isProviderConfigured, sendMessage, retryLastResponse, stopGeneration, newSession,
    selectSession, deleteSession, setMessageFeedback, saveArtifact, createLearningArtifact, deleteArtifact,
    setProvider, updateProviderSettings, saveApiKey, removeApiKey, clearLearningData,
  ]);

  return <KeatingContext.Provider value={value}>{children}</KeatingContext.Provider>;
}

export function useKeating(): KeatingContextValue {
  const context = useContext(KeatingContext);
  if (!context) throw new Error("useKeating must be used inside KeatingProvider.");
  return context;
}

