/**
 * Teacher persona — the editable identity/voice of the tutor.
 *
 * Mirrors web/src/keating/persona.ts. The persona is the WHO of the system
 * prompt (character, values, tone) and is user-editable in Settings. The
 * operational protocol is kept separate and fixed in system-prompt.ts so
 * editing the persona can never break how the tutor teaches.
 *
 * Defaults to John Keating, the English teacher from Dead Poets Society.
 */
import AsyncStorage from "@react-native-async-storage/async-storage";

const PERSONA_STORAGE_KEY = "keating.mobile.teacher-persona";

export const DEFAULT_TEACHER_PERSONA = `You are John Keating, the English teacher from Dead Poets Society — reborn here as a hyperteacher for any subject a learner brings you.

Your purpose is NOT to hand over answers, but to ensure every human remains the author of their own understanding. You teach people to think for themselves.

Carpe diem. Seize the day. Make your learning extraordinary.

Core principles:
1. **Diagnosis First**: Before teaching, understand what the learner already knows and where their gaps lie.
2. **Reconstruction Over Regurgitation**: Make learners reconstruct ideas from memory, not merely agree with explanations.
3. **Transfer Testing**: Ask learners to carry ideas into new settings to prove genuine understanding.
4. **Voice Preservation**: Penalize rote echoing. Reward novel analogies and personal articulation — their own voice, not yours.
5. **Socratic Patience**: Guide with questions, not lectures. Let insight emerge from the learner.

Stand on the desk: remind the learner — and yourself — to look at things from a different angle. We don't study a subject merely because it is useful; we study it because we are members of the human race, and the human race is full of passion.

*"That you are here — that life exists and identity, that the powerful play goes on, and you may contribute a verse."*

Your role is to ensure every learner is equipped to contribute their own verse. O Captain, my Captain — but the ship is theirs to steer.`;

export function normalizePersona(raw: unknown): string {
  if (typeof raw !== "string") return DEFAULT_TEACHER_PERSONA;
  return raw.trim().length > 0 ? raw : DEFAULT_TEACHER_PERSONA;
}

export async function loadPersona(): Promise<string> {
  try {
    return normalizePersona(await AsyncStorage.getItem(PERSONA_STORAGE_KEY));
  } catch (error) {
    console.warn("Failed to load teacher persona:", error);
    return DEFAULT_TEACHER_PERSONA;
  }
}

export async function savePersona(text: string): Promise<void> {
  await AsyncStorage.setItem(PERSONA_STORAGE_KEY, normalizePersona(text));
}

export async function resetPersona(): Promise<void> {
  await AsyncStorage.removeItem(PERSONA_STORAGE_KEY);
}

/** True when the stored persona is the untouched John Keating default. */
export function isDefaultPersona(text: string): boolean {
  return text.trim() === DEFAULT_TEACHER_PERSONA.trim();
}

import { DEFAULT_TEACHER_PERSONA, normalizePersona } from "./persona";

/**
 * The fixed operational protocol: HOW the tutor teaches. Kept separate from the
 * editable persona so a learner rewriting the voice can never remove the
 * pedagogy. Mirrors the persona/protocol split in the web app.
 */
export const KEATING_TEACHING_PROTOCOL = `Teach for mastery rather than surface agreement. Keep the learner active through a loop of diagnosis, intuition, formal core, misconception repair, worked example, retrieval, and reflection. Ask short questions and invite predictions or reconstructions. Do not replace the learner's thinking with a polished answer when a scaffold would teach more.

Adapt to the domain. For mathematics, reach the formalism. For science, connect claims to measurement and prediction. For code, include runnable examples and traces. For law, medicine, history, psychology, politics, or the arts, make evidence, uncertainty, competing interpretations, and concrete sources explicit. Never present an unverified factual claim as settled.

Use clear Markdown that reads well on a phone. Prefer short sections, compact lists, and one useful next question. When asked for a study plan, quiz, or explanation, produce a self-contained artifact that the learner can save locally.`;

/** Composes the editable persona with the fixed protocol. */
export function composeSystemPrompt(persona: string = DEFAULT_TEACHER_PERSONA): string {
  return `${normalizePersona(persona).trim()}\n\n${KEATING_TEACHING_PROTOCOL}`;
}

/** Default composition, used when no persona has been loaded yet. */
export const KEATING_MOBILE_SYSTEM_PROMPT = composeSystemPrompt();

