  const body = response.body;
  if (!body) {
    // No readable stream on this platform or provider — take the whole payload.
    const text = await response.text();
    const content = extractProviderText(settings, text ? JSON.parse(text) : {});
    onDelta?.(content, content);
    return content;
  }

  const decoder = new TextDecoder();
  const parse = createSseParser();
  const reader = body.getReader();
  let accumulated = "";

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      for (const data of parse(decoder.decode(value, { stream: true }))) {
        const delta = extractStreamDelta(settings, data);
        if (!delta) continue;
        accumulated += delta;
        onDelta?.(delta, accumulated);
      }
    }
  } finally {
    reader.releaseLock();
  }

  const trimmed = accumulated.trim();
  if (!trimmed) throw new Error("The provider returned a response without readable text.");
  return trimmed;
}

