const generatedImageTagPattern = new RegExp(String.raw`<keating-image\s+json=${TAG_PAYLOAD}\s*\/>`, "g");
const quizResultTagPattern = new RegExp(String.raw`<keating-quiz-result\s+json=${TAG_PAYLOAD}\s*\/>`, "g");
