	const defaultLearner: LearnerProfile = {
		id: "real-learner",
		priorKnowledge: 0.5,
		abstractionComfort: 0.5,
		analogyNeed: 0.5,
		dialoguePreference: 0.5,
		diagramAffinity: 0.5,
		persistence: 0.5,
		transferDesire: 0.5,
		anxiety: 0.3,
	};

	const avgOutcome = mean(outcomes.map((outcome) => outcome.outcomeScore));
	const upRatio =
		outcomes.filter((outcome) => outcome.feedbackSignal === "thumbs-up").length /
		outcomes.length;
	const confusedRatio =
		outcomes.filter((outcome) => outcome.feedbackSignal === "confused").length /
		outcomes.length;
	const downRatio =
		outcomes.filter((outcome) => outcome.feedbackSignal === "thumbs-down").length /
		outcomes.length;
	const avgMastery = mean(outcomes.map((outcome) => outcome.masteryEstimate));
	const quizScores = outcomes
		.map((outcome) => outcome.quizScore)
		.filter((value): value is number => typeof value === "number" && !Number.isNaN(value));
	const avgQuiz = quizScores.length > 0 ? mean(quizScores) : null;

	// Graded quiz results are direct evidence of mastery, so when present they
	// dominate the inferred feedback/mastery signals.
	const masteryGain =
		avgQuiz === null
			? clamp(avgOutcome * 0.6 + avgMastery * 0.4)
			: clamp(avgQuiz * 0.5 + avgOutcome * 0.3 + avgMastery * 0.2);
	const retention = clamp(
		masteryGain * (0.55 + policy.retrievalPractice * 0.45)
