			items: items && items.length > 0 ? items : undefined,
			multiSelect,
			allowText,
			blanks,
			requireReasons,
			itemLabel: typeof q.itemLabel === "string" ? q.itemLabel : typeof q.item_label === "string" ? q.item_label : undefined,
