7	function markdownBlocks(content: string): Block[] {
8	  const blocks: Block[] = [];
9	  const expression = /```([^\n`]*)\n?([\s\S]*?)```/g;
10	  let cursor = 0;
11	  for (const match of content.matchAll(expression)) {
12	    const index = match.index ?? 0;
13	    if (index > cursor) blocks.push({ type: "text", value: content.slice(cursor, index) });
14	    blocks.push({ type: "code", language: match[1].trim(), value: match[2].trimEnd() });
15	    cursor = index + match[0].length;
16	  }
17	  if (cursor < content.length) blocks.push({ type: "text", value: content.slice(cursor) });
18	  return blocks.length > 0 ? blocks : [{ type: "text", value: content }];
19	}
