21	function Spoiler({ children }: { children: string }) {
22	  const [revealed, setRevealed] = useState(false);
23	  return (
24	    <Text
25	      accessibilityRole="button"
26	      accessibilityLabel={revealed ? "Hide answer" : "Reveal answer"}
27	      accessibilityState={{ expanded: revealed }}
28	      onPress={() => setRevealed((current) => !current)}
29	      style={revealed ? styles.spoilerRevealed : styles.spoilerHidden}
30	    >
31	      {revealed ? children : "Tap to reveal"}
32	    </Text>
33	  );
34	}
