36	function inlineNodes(value: string): ReactNode[] {
37	  const nodes: ReactNode[] = [];
38	  const expression = /(\|\|[^|]+\|\||\*\*[^*]+\*\*|`[^`]+`|\[[^\]]+\]\([^)]+\))/g;
39	  let cursor = 0;
40	  let key = 0;
41	  for (const match of value.matchAll(expression)) {
42	    const index = match.index ?? 0;
43	    if (index > cursor) nodes.push(value.slice(cursor, index));
44	    const token = match[0];
45	    if (token.startsWith("||")) {
46	      nodes.push(<Spoiler key={key++}>{token.slice(2, -2)}</Spoiler>);
47	    } else if (token.startsWith("**")) {
48	      nodes.push(<Text key={key++} style={styles.bold}>{token.slice(2, -2)}</Text>);
49	    } else if (token.startsWith("`")) {
50	      nodes.push(<Text key={key++} style={styles.inlineCode}>{token.slice(1, -1)}</Text>);
51	    } else {
52	      const link = token.match(/^\[([^\]]+)\]\(([^)]+)\)$/);
53	      if (link) {
54	        nodes.push(
55	          <Text key={key++} style={styles.link} accessibilityRole="link" onPress={() => void Linking.openURL(link[2])}>
56	            {link[1]}
57	          </Text>,
58	        );
59	      }
60	    }
61	    cursor = index + token.length;
62	  }
63	  if (cursor < value.length) nodes.push(value.slice(cursor));
64	  return nodes;
65	}
