67	function TextBlock({ value }: { value: string }) {
68	  const lines = value.split("\n");
69	  return (
70	    <View style={styles.textBlock}>
71	      {lines.map((rawLine, index) => {
72	        const line = rawLine.trimEnd();
73	        if (!line.trim()) return <View key={index} style={styles.spacer} />;
74	        const heading = line.match(/^(#{1,3})\s+(.+)$/);
75	        if (heading) {
76	          return <Text key={index} style={[styles.paragraph, heading[1].length === 1 ? styles.h1 : styles.h2]}>{inlineNodes(heading[2])}</Text>;
77	        }
78	        const bullet = line.match(/^\s*[-*]\s+(.+)$/);
79	        if (bullet) {
80	          return (
81	            <View key={index} style={styles.listRow}>
82	              <Text style={styles.bullet}>•</Text>
83	              <Text style={[styles.paragraph, styles.listText]}>{inlineNodes(bullet[1])}</Text>
84	            </View>
85	          );
86	        }
87	        const numbered = line.match(/^\s*(\d+)\.\s+(.+)$/);
88	        if (numbered) {
89	          return (
90	            <View key={index} style={styles.listRow}>
91	              <Text style={styles.number}>{numbered[1]}.</Text>
92	              <Text style={[styles.paragraph, styles.listText]}>{inlineNodes(numbered[2])}</Text>
93	            </View>
94	          );
95	        }
96	        if (line.startsWith("> ")) {
97	          return <Text key={index} style={[styles.paragraph, styles.quote]}>{inlineNodes(line.slice(2))}</Text>;
98	        }
99	        return <Text key={index} style={styles.paragraph}>{inlineNodes(line)}</Text>;
100	      })}
101	    </View>
102	  );
103	}
104	
105	export function MarkdownText({ content }: { content: string }) {
106	  return (
107	    <View>
108	      {markdownBlocks(content).map((block, index) => (
109	        <Fragment key={index}>
110	          {block.type === "code" ? (
111	            <View style={styles.codeFrame}>
112	              {block.language ? <Text style={styles.codeLanguage}>{block.language}</Text> : null}
113	              <ScrollView horizontal showsHorizontalScrollIndicator contentContainerStyle={styles.codeScroller}>
114	                <Text selectable style={styles.code}>{block.value}</Text>
115	              </ScrollView>
116	            </View>
117	          ) : <TextBlock value={block.value} />}
118	        </Fragment>
119	      ))}
120	    </View>
121	  );
122	}
