/**
 * Parsing for the `<keating-… />` interactive tags the teacher emits inline.
 *
 * The web app produces these tags from browser tools; the mobile app has no
 * tool loop, so the teaching protocol asks the model to emit them directly in
 * its reply. Either way the wire format is identical: an attribute holding a
 * double-stringified JSON payload.
 *
 * This module is deliberately free of React Native imports so the parsing and
 * normalization can be exercised under plain `bun test`.
 */

/** A quiz question as authored by the teacher. */
export interface QuizQuestion {
  id: string;
  type: "multiple_choice" | "short_answer" | "true_false" | "fill_in" | "transfer";
  level: "recall" | "comprehension" | "application" | "analysis" | "transfer";
  question: string;
  options?: string[];
  blanks?: { placeholder?: string; hint?: string }[];
  correctAnswer: string;
  correctAnswers?: string[];
  explanation: string;
  rubric?: string;
}

export interface Quiz {
  topic: string;
  slug: string;
  questions: QuizQuestion[];
}

/** One field of an ask-the-learner form. */
export interface QuestionField {
  header?: string;
  question: string;
  type?: "choice" | "text" | "blanks";
  choices?: string[];
  blanks?: { placeholder?: string; hint?: string }[];
  multiSelect: boolean;
  allowText: boolean;
  hint?: string;
}

export interface QuestionForm {
  intro?: string;
  topic?: string;
  questions: QuestionField[];
}

export type GoalStepStatus = "not_started" | "in_progress" | "done";
export type GoalStepKind = "concept" | "practice" | "project" | "milestone" | "reflection";

export interface GoalStep {
  id: string;
  order: number;
  title: string;
  description: string;
  kind: GoalStepKind;
  successCriteria: string[];
  status: GoalStepStatus;
}

export interface LearnerGoal {
  id: string;
  title: string;
  description: string;
  steps: GoalStep[];
}

export type InteractiveSegment =
  | { type: "text"; content: string }
  | { type: "quiz"; quiz: Quiz }
  | { type: "question"; form: QuestionForm }
  | { type: "goal"; goal: LearnerGoal };

// Payloads are JSON string literals and may contain literal ">" characters, so
// match a complete quoted string first and only fall back to the legacy
// "anything up to >" form for older unquoted payloads.
const TAG_PAYLOAD = String.raw`("(?:[^"\\]|\\.)*"|[^>]+)`;
const TAG_PATTERN = new RegExp(String.raw`<keating-(quiz|question|goal)\s+json=${TAG_PAYLOAD}\s*\/>`, "g");

/**
 * Decodes a tag attribute. Tools double-stringify the payload; hand-written
 * tags from a model sometimes only stringify it once, so unwrap until an
 * object falls out.
 */
export function decodeTagPayload(raw: string): unknown {
  let value: unknown;
  try {
    value = JSON.parse(raw);
  } catch {
    return null;
  }
  for (let depth = 0; typeof value === "string" && depth < 3; depth += 1) {
    try {
      value = JSON.parse(value);
    } catch {
      return null;
    }
  }
  return value;
}

function asString(value: unknown, fallback = ""): string {
  return typeof value === "string" ? value : fallback;
}

function asStringArray(value: unknown): string[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const items = value.filter((item): item is string => typeof item === "string");
  return items.length > 0 ? items : undefined;
}

function asBlanks(value: unknown): { placeholder?: string; hint?: string }[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const blanks = value
    .filter((blank): blank is Record<string, unknown> => !!blank && typeof blank === "object")
    .map((blank) => ({
      placeholder: typeof blank.placeholder === "string" ? blank.placeholder : undefined,
      hint: typeof blank.hint === "string" ? blank.hint : undefined,
    }));
  return blanks.length > 0 ? blanks : undefined;
}

const QUESTION_TYPES = ["multiple_choice", "short_answer", "true_false", "fill_in", "transfer"] as const;
const BLOOM_LEVELS = ["recall", "comprehension", "application", "analysis", "transfer"] as const;

function normalizeQuizQuestion(raw: unknown, index: number): QuizQuestion | null {
  if (!raw || typeof raw !== "object") return null;
  const q = raw as Record<string, unknown>;
  const question = asString(q.question).trim();
  const correctAnswer = asString(q.correctAnswer ?? q.correct_answer).trim();
  if (!question || !correctAnswer) return null;

  const options = asStringArray(q.options);
  const blanks = asBlanks(q.blanks);
  const declared = asString(q.type);
  const type = (QUESTION_TYPES as readonly string[]).includes(declared)
    ? (declared as QuizQuestion["type"])
    : options
      ? "multiple_choice"
      : "short_answer";
  const level = (BLOOM_LEVELS as readonly string[]).includes(asString(q.level))
    ? (asString(q.level) as QuizQuestion["level"])
    : "recall";

  // A multiple-choice question whose key is missing from the options would be
  // unanswerable, so fold it back in.
  const withAnswer = options && !options.some((option) => option.trim().toLowerCase() === correctAnswer.toLowerCase())
    ? [...options, correctAnswer]
    : options;

  return {
    id: asString(q.id) || `q${index + 1}`,
    type,
    level,
    question,
    options: type === "multiple_choice" ? withAnswer : undefined,
    blanks,
    correctAnswer,
    correctAnswers: asStringArray(q.correctAnswers ?? q.correct_answers),
    explanation: asString(q.explanation),
    rubric: asString(q.rubric) || undefined,
  };
}

/** Returns a renderable quiz, or null when the payload has no usable questions. */
export function normalizeQuiz(raw: unknown): Quiz | null {
  if (!raw || typeof raw !== "object") return null;
  const obj = raw as Record<string, unknown>;
  const source = Array.isArray(obj.questions) ? obj.questions : [];
  const questions = source
    .map((entry, index) => normalizeQuizQuestion(entry, index))
    .filter((entry): entry is QuizQuestion => entry !== null);
  if (questions.length === 0) return null;
  const topic = asString(obj.topic) || asString(obj.title) || "this lesson";
  return { topic, slug: asString(obj.slug) || topic.toLowerCase().replace(/\s+/g, "-"), questions };
}

function normalizeQuestionField(raw: unknown): QuestionField | null {
  if (!raw || typeof raw !== "object") return null;
  const q = raw as Record<string, unknown>;
  const question = asString(q.question).trim();
  if (!question) return null;

  const choices = asStringArray(q.choices);
  const blanks = asBlanks(q.blanks);
  const multiSelect = q.multiSelect === true || q.multi_select === true;
  const allowText = typeof q.allowText === "boolean"
    ? q.allowText
    : typeof q.allow_text === "boolean"
      ? q.allow_text
      : !choices;
  const declared = asString(q.type);
  const type: QuestionField["type"] = blanks
    ? "blanks"
    : declared === "choice" || declared === "text" || declared === "blanks"
      ? declared
      : choices
        ? "choice"
        : "text";

  return {
    header: asString(q.header) || undefined,
    question,
    type,
    choices,
    blanks,
    multiSelect,
    allowText,
    hint: asString(q.hint) || undefined,
  };
}

/**
 * Accepts the multi-field shape `{ questions: [...] }` or a single question
 * object, and returns a normalized form. Null when nothing is renderable.
 */
export function normalizeQuestionForm(raw: unknown): QuestionForm | null {
  if (!raw || typeof raw !== "object") return null;
  const obj = raw as Record<string, unknown>;
  const intro = asString(obj.intro) || undefined;
  const topic = asString(obj.topic) || undefined;

  if (Array.isArray(obj.questions)) {
    const questions = obj.questions
      .map(normalizeQuestionField)
      .filter((field): field is QuestionField => field !== null);
    if (questions.length === 0) return null;
    return { intro, topic, questions };
  }

  const single = normalizeQuestionField(obj);
  return single ? { intro, topic, questions: [single] } : null;
}

const STEP_KINDS = ["concept", "practice", "project", "milestone", "reflection"] as const;
const STEP_STATUSES = ["not_started", "in_progress", "done"] as const;

/** Returns a renderable goal, or null when the payload has no usable steps. */
export function normalizeGoal(raw: unknown): LearnerGoal | null {
  if (!raw || typeof raw !== "object") return null;
  const obj = raw as Record<string, unknown>;
  const title = asString(obj.title).trim();
  if (!title) return null;
  const source = Array.isArray(obj.steps) ? obj.steps : [];
  const steps = source
    .filter((step): step is Record<string, unknown> => !!step && typeof step === "object")
    .map((step, index) => {
      const stepTitle = asString(step.title).trim();
      if (!stepTitle) return null;
      const kind = asString(step.kind);
      const status = asString(step.status);
      return {
        id: asString(step.id) || `step-${index + 1}`,
        order: typeof step.order === "number" ? step.order : index,
        title: stepTitle,
        description: asString(step.description),
        kind: (STEP_KINDS as readonly string[]).includes(kind) ? (kind as GoalStepKind) : "concept",
        successCriteria: asStringArray(step.successCriteria ?? step.success_criteria) ?? [],
        status: (STEP_STATUSES as readonly string[]).includes(status) ? (status as GoalStepStatus) : "not_started",
      } satisfies GoalStep;
    })
    .filter((step): step is GoalStep => step !== null);
  if (steps.length === 0) return null;
  return { id: asString(obj.id) || `goal-${title.toLowerCase().replace(/\s+/g, "-")}`, title, description: asString(obj.description), steps };
}

/**
 * Splits assistant text into plain-text runs and the interactive cards embedded
 * in it. Malformed tags are dropped rather than shown as raw markup.
 */
export function parseInteractiveSegments(text: string): InteractiveSegment[] {
  const segments: InteractiveSegment[] = [];
  let lastIndex = 0;

  const pushText = (content: string) => {
    if (content.trim().length > 0) segments.push({ type: "text", content });
  };

  for (const match of text.matchAll(TAG_PATTERN)) {
    const index = match.index ?? 0;
    pushText(text.slice(lastIndex, index));
    lastIndex = index + match[0].length;

    const payload = decodeTagPayload(match[2]);
    if (payload === null) continue;
    if (match[1] === "quiz") {
      const quiz = normalizeQuiz(payload);
      if (quiz) segments.push({ type: "quiz", quiz });
    } else if (match[1] === "question") {
      const form = normalizeQuestionForm(payload);
      if (form) segments.push({ type: "question", form });
    } else {
      const goal = normalizeGoal(payload);
      if (goal) segments.push({ type: "goal", goal });
    }
  }

  pushText(text.slice(lastIndex));
  if (segments.length === 0) segments.push({ type: "text", content: text });
  return segments;
}

/** True when the text carries at least one well-formed interactive card. */
export function hasInteractiveCard(text: string): boolean {
  return parseInteractiveSegments(text).some((segment) => segment.type !== "text");
}

/** Strips every interactive tag, leaving the prose the model wrote around it. */
export function stripInteractiveTags(text: string): string {
  return text.replace(TAG_PATTERN, "").trim();
}

/**
 * Local grading for quiz cards, ported from the web renderer.
 *
 * Objective question types are graded exactly; open-ended ones only get a
 * partial-credit estimate here, because the authoritative judgment comes from
 * the teacher when the answers are reported back into the conversation.
 *
 * React Native imports stay out of this module so it can run under `bun test`.
 */
import type { QuestionField, QuizQuestion } from "./interactive-tags";

function tokenize(text: string): string[] {
  return text.toLowerCase().replace(/[^a-z0-9 ]/g, "").split(/\s+/).filter(Boolean);
}

function ngrams(tokens: string[], n: number): string[] {
  if (tokens.length < n) return [];
  const grams: string[] = [];
  for (let i = 0; i <= tokens.length - n; i += 1) grams.push(tokens.slice(i, i + n).join(" "));
  return grams;
}

// Fraction of the reference's n-grams that appear in the answer. Bigrams reward
// phrasing and word order, which single-token overlap misses.
function ngramRecall(answerTokens: string[], referenceTokens: string[], n: number): number {
  const reference = ngrams(referenceTokens, n);
  if (reference.length === 0) return 0;
  const answer = new Set(ngrams(answerTokens, n));
  return reference.filter((gram) => answer.has(gram)).length / reference.length;
}

function levenshtein(a: string, b: string): number {
  const m = a.length;
  const n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  const prev = Array.from({ length: n + 1 }, (_, i) => i);
  const curr = new Array<number>(n + 1);
  for (let i = 1; i <= m; i += 1) {
    curr[0] = i;
    const ac = a[i - 1];
    for (let j = 1; j <= n; j += 1) {
      curr[j] = ac === b[j - 1] ? prev[j - 1] : 1 + Math.min(prev[j - 1], curr[j - 1], prev[j]);
    }
    for (let j = 0; j <= n; j += 1) prev[j] = curr[j];
  }
  return prev[n];
}

/** Fraction of the point awarded for an answer, between 0 and 1. */
export function questionCredit(question: QuizQuestion, rawAnswer: string): number {
  if (!rawAnswer.trim()) return 0;

  if (question.type === "fill_in" && question.blanks && question.blanks.length > 0) {
    const given = rawAnswer.split("|").map((value) => value.trim());
    const expected = question.correctAnswers ?? [question.correctAnswer];
    let correct = 0;
    for (let i = 0; i < Math.min(given.length, expected.length); i += 1) {
      if (given[i].toLowerCase() === expected[i].trim().toLowerCase()) correct += 1;
    }
    return correct / expected.length;
  }

  if (question.type === "true_false" || question.type === "multiple_choice") {
    return rawAnswer.trim().toLowerCase() === question.correctAnswer.trim().toLowerCase() ? 1 : 0;
  }

  // Open-ended: there is no single correct string, so take the most generous of
  // several similarity signals and let the teacher give the real verdict.
  const answer = rawAnswer.trim().toLowerCase();
  const reference = question.correctAnswer.trim().toLowerCase();
  if (answer === reference) return 1;
  const distance = levenshtein(answer, reference);
  const editScore = Math.max(0, 1 - distance / (Math.max(answer.length, reference.length) || 1));
  const answerTokens = tokenize(answer);
  const referenceTokens = tokenize(reference);
  const answerSet = new Set(answerTokens);
  const overlap = referenceTokens.filter((token) => answerSet.has(token)).length;
  const keywordScore = referenceTokens.length ? overlap / referenceTokens.length : 0;
  return Math.max(editScore, keywordScore * 0.9, ngramRecall(answerTokens, referenceTokens, 2));
}

/** True when only the teacher can really judge the answer. */
export function isOpenEnded(question: QuizQuestion): boolean {
  if (question.type === "short_answer" || question.type === "transfer") return true;
  // Single-blank fill_in is free text; multi-blank fill_in is graded per blank.
  return question.type === "fill_in" && !(question.blanks && question.blanks.length > 0);
}

// Open-ended answers can't be graded by string equality, so accept anything
// close enough locally rather than showing a misleadingly strict score.
const OPEN_ENDED_CREDIT_THRESHOLD = 0.6;

export function isCorrect(question: QuizQuestion, rawAnswer: string): boolean {
  if (question.type === "fill_in" && question.blanks && question.blanks.length > 0) {
    const given = rawAnswer.split("|").map((value) => value.trim());
    const expected = question.correctAnswers ?? [question.correctAnswer];
    if (given.length !== expected.length) return false;
    return given.every((value, index) => value.toLowerCase() === expected[index].trim().toLowerCase());
  }
  if (isOpenEnded(question)) return questionCredit(question, rawAnswer) >= OPEN_ENDED_CREDIT_THRESHOLD;
  return rawAnswer.trim().toLowerCase() === question.correctAnswer.trim().toLowerCase();
}

export interface QuizScore {
  /** Questions marked correct outright. */
  correct: number;
  total: number;
  /** Sum of partial credit, so open-ended near-misses still count for something. */
  weighted: number;
  percent: number;
  hasOpenEnded: boolean;
}

export function scoreQuiz(questions: QuizQuestion[], answers: Record<string, string>): QuizScore {
  let correct = 0;
  let weighted = 0;
  for (const question of questions) {
    const answer = answers[question.id] ?? "";
    if (isCorrect(question, answer)) correct += 1;
    weighted += questionCredit(question, answer);
  }
  const total = questions.length;
  return {
    correct,
    total,
    weighted,
    percent: total === 0 ? 0 : Math.round((weighted / total) * 100),
    hasOpenEnded: questions.some(isOpenEnded),
  };
}

/**
 * Builds the user turn sent back to the teacher after a quiz. Open-ended items
 * are flagged explicitly so the teacher knows which answers still need a real
 * verdict.
 */
export function buildQuizReport(topic: string, questions: QuizQuestion[], answers: Record<string, string>): string {
  const score = scoreQuiz(questions, answers);
  const lines = [
    `I finished the ${topic} quiz: ${score.correct}/${score.total} correct (${score.percent}% with partial credit).`,
    "",
  ];
  for (const question of questions) {
    const answer = (answers[question.id] ?? "").trim() || "(blank)";
    if (isOpenEnded(question)) {
      lines.push(`- [open-ended] ${question.question} → my answer: "${answer}" (reference: "${question.correctAnswer}")`);
    } else {
      lines.push(`- ${question.question} → my answer: "${answer}" ${isCorrect(question, answers[question.id] ?? "") ? "✓" : "✗"}`);
    }
  }
  lines.push("");
  if (score.hasOpenEnded) {
    lines.push(
      "Grade the open-ended answers by meaning rather than exact wording — the reference is one acceptable answer, not the only one.",
    );
  }
  lines.push("Review what I missed and tell me what to work on next.");
  return lines.join("\n");
}

/** Builds the user turn sent back after an ask-the-learner form. */
export function buildQuestionReport(
  fields: QuestionField[],
  answers: string[],
  topic?: string,
): string {
  const lines = [topic ? `Here are my answers about ${topic}:` : "Here are my answers:", ""];
  fields.forEach((field, index) => {
    const answer = (answers[index] ?? "").trim() || "(skipped)";
    lines.push(`- ${field.header ? `${field.header}: ` : ""}${field.question} → ${answer}`);
  });
  lines.push("");
  lines.push("Use these to pitch the next step at the right level.");
  return lines.join("\n");
}

/**
 * In-memory answers for interactive cards.
 *
 * Cards live inside the chat FlatList, which unmounts rows that scroll far off
 * screen. Keeping submitted answers here — keyed by message id and position —
 * means a card the learner already completed comes back completed rather than
 * blank. The submitted answers are also echoed into the transcript as a user
 * turn, so nothing durable is lost when the app restarts.
 */
const store = new Map<string, unknown>();

export function cardKey(messageId: string, index: number): string {
  return `${messageId}:${index}`;
}

export function readCardState<T>(key: string): T | undefined {
  return store.get(key) as T | undefined;
}

export function writeCardState(key: string, value: unknown): void {
  store.set(key, value);
}

/** Drops every remembered answer; used when local learning data is cleared. */
export function clearCardState(): void {
  store.clear();
}

